function get(course){const r=routes[String(course.id)];return r&&CourseInfo.sourceURL(course.desc)===r.source?r:null;}
for(const r of Object.values(routes)){const stops=[];let text='',balance=0;for(const part of r.waypoints){text+=(text?', ':'')+part;balance+=(part.match(/[(]/g)||[]).length-(part.match(/[)]/g)||[]).length;if(balance<=0){stops.push(text);text='';balance=0;}}if(text)stops.push(text);r.waypoints=stops;}
function endpointDistance(path){const a=path[0],b=path[path.length-1],rad=Math.PI/180;const x=(b[1]-a[1])*rad*Math.cos((a[0]+b[0])/2*rad),y=(b[0]-a[0])*rad;return Math.sqrt(x*x+y*y)*6371000;}
root.CourseRoutes=Object.freeze({get,isLoop:r=>!r.parts&&endpointDistance(r.path)<=30});
